/**
 * Build the Tauri frontend: the workspace shell as a static asset.
 *
 * The page is generated by `renderPyCharmHtml()` — the same function the dev
 * server returns over HTTP — so the Tauri bundle gets *byte-identical* markup
 * and there is no second implementation of the UI to drift.
 *
 * Only the workspace shell is emitted. `/monitor`, `/perf` and `/extensions`
 * stay behind the dev server: they speak WebSocket to a host they expect on
 * `location.host`, which does not exist in a Tauri build.
 *
 * Run: node scripts/build-frontend.mjs
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { renderPyCharmHtml } from '../src/panel/pycharm-ui.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'frontend', 'dist');

const html = renderPyCharmHtml(0);

// The same invariants the jsdom suite enforces, checked here so a regression
// cannot silently produce a bundle that depends on the network.
const problems = [];
if (/<script[^>]+src=/i.test(html)) problems.push('external <script src>');
if (/<link[^>]+href=/i.test(html)) problems.push('external <link>');
if (/@import/i.test(html)) problems.push('CSS @import');
if (/(unpkg|jsdelivr|cdnjs|googleapis)/i.test(html)) problems.push('CDN reference');
if (problems.length) {
  console.error(`build-frontend: the page is not self-contained — ${problems.join(', ')}`);
  process.exit(1);
}

await mkdir(outDir, { recursive: true });
await writeFile(join(outDir, 'index.html'), html, 'utf8');

console.log(`build-frontend: wrote frontend/dist/index.html (${html.length} bytes, self-contained)`);
